import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"このアプリについて","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/others/"}],["meta",{"property":"og:title","content":"このアプリについて | 青い星のハンターノート"}],["meta",{"property":"og:description","content":"ワイルズ、ライズとサンブレイク、ワールドとアイスボーンのデータと装備検索。"}]]},"headers":[],"relativePath":"ja-jp/others/index.md","filePath":"ja-jp/others/index.md"}'),i={name:"ja-jp/others/index.md"};function n(p,e,h,l,s,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="このアプリについて" tabindex="-1">このアプリについて <a class="header-anchor" href="#このアプリについて" aria-label="Permalink to &quot;このアプリについて&quot;">​</a></h1><h2 id="アプリ概要" tabindex="-1">アプリ概要 <a class="header-anchor" href="#アプリ概要" aria-label="Permalink to &quot;アプリ概要&quot;">​</a></h2><p>Sapphire Star Codex は、<a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a> の開発者による独立した非営利のモンスターハンター向けアプリです。広告・有料機能はありません。</p><h2 id="開発を支援" tabindex="-1">開発を支援 <a class="header-anchor" href="#開発を支援" aria-label="Permalink to &quot;開発を支援&quot;">​</a></h2><p><a href="./../support/">開発を支援</a>ページから、Alipay または WeChat Pay で任意の支援ができます。支援の有無によって利用できる機能は変わりません。</p><h2 id="プロジェクトへの協力" tabindex="-1">プロジェクトへの協力 <a class="header-anchor" href="#プロジェクトへの協力" aria-label="Permalink to &quot;プロジェクトへの協力&quot;">​</a></h2><p>HarmonyOS版は<a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">Huawei AppGallery</a>で配信中です。Android版は<a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>で配信中です。iOS版は公開に向けて準備中です。</p><p>サイトの紹介や翻訳の確認が助けになります。データの問題には、作品と拡張コンテンツ、項目名、言語、正しい値、確認できる出典を添えてください。画像に個人情報を含めないでください。</p><p>開発者や今後の連絡先は<a href="https://github.com/eurekaffeine" target="_blank" rel="noreferrer">公開プロフィール</a>で確認できます。このサイトには現在フィードバックフォームはありません。</p><h2 id="データと画像" tabindex="-1">データと画像 <a class="header-anchor" href="#データと画像" aria-label="Permalink to &quot;データと画像&quot;">​</a></h2><p>作品別にデータを抽出・整理しています。<a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>、<a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a>、ゲームファイルからの抽出を使い、コミュニティ資料で照合します。欠落や誤りがある可能性があり、完全な収録を保証するものではありません。</p><h2 id="免責事項" tabindex="-1">免責事項 <a class="header-anchor" href="#免責事項" aria-label="Permalink to &quot;免責事項&quot;">​</a></h2><p>このサイトは Sapphire Star Codex プロジェクトのものです。アプリは CAPCOM と関係がなく、承認・支援を受けていません。Monster Hunter の名称、デザイン、公式アイコン、ゲームデータは CAPCOM Co., Ltd. に帰属します。非営利のファンプロジェクトとして、権利者からの削除要請を尊重します。</p><p>ウェブサイトは Pocket Gallery の MIT ライセンスの VitePress コンポーネントを基にしています。このコードのライセンスはゲーム画像・データには適用されません。</p>',14)])])}const u=a(i,[["render",n]]);export{f as __pageData,u as default};
